/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to Order guides and add entry to Price Change tracking table for later processing
/// </summary>
abstract class METPriceChangeEventOrderGuide extends METPriceChangeEvent
{
    METSalesOrderGuideItem      salesOrderGuideItem;

}

Method.Source:
/// <summary>
/// Initialise the instance
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void initInstance(Common _common, SysAppCRUDOperation _crud)
{
    this.setInternals(_Common, _crud);
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_common">Table record</param>
/// <param name = "_crud">DB operation</param>
public void setInternals(Common _common, SysAppCRUDOperation _crud)
{
    super(_common, _crud);
    salesOrderGuideItem       = _common as METSalesOrderGuideItem;
}

    /// <summary>
    /// Process the base record that triggered the change
    /// </summary>
    public void process()
    {
        switch(salesOrderGuideItem.referenceType)
        {
            case METSalesOrderGuideReferenceType::Customer :
                this.ProcessCustomer(CustTable::find(salesOrderGuideItem.Reference));
                break;
            
            case METSalesOrderGuideReferenceType::CustomerOperationsGroup :
                this.ProcessCustomerGroup();
                break;
            
            case METSalesOrderGuideReferenceType::Site :
                this.ProcessSite();
                break;

            case METSalesOrderGuideReferenceType::State :
                this.ProcessState();
                break;
        }
        
        ttsbegin;
        priceChangeTrackingList.insertDatabase();
        ttscommit;
    }

    /// <summary>
    /// Process the base record that triggered the change
    /// </summary>
    /// <param name = "_custTable">Customer</param>
    public void processCustomer(CustTable _custTable)
    {
        priceChangeTracking.clear();
        this.setCommonValues(salesOrderGuideItem);
        priceChangeTracking.ItemId              = salesOrderGuideItem.ItemId;
        priceChangeTracking.CustAccount         = _custTable.AccountNum;
        priceChangeTracking.InventSiteId        = _custTable.InventSiteId;
        priceChangeTracking.FromDate            = todayDate;
        priceChangeTracking.QuantityAmountFrom  = 1;
        priceChangeTracking.QuantityAmountTo    = priceChangeTracking.QuantityAmountFrom;
        priceChangeTracking.PriceDiscAccountRelation  = _custTable.AccountNum;
        priceChangeTracking.UnitId              = InventTableModule::find(salesOrderGuideItem.ItemId, ModuleInventPurchSales::Sales).UnitId;

        priceChangeTrackingList.add(priceChangeTracking);
    }

    /// <summary>
    /// Process the base record that triggered the change
    /// </summary>
    public void processCustomerGroup()
    {
        METCustTable    metCustTable;
        CustTable       custTable;

        while select custTable
            exists join metCustTable
            where   metCustTable.AccountNum         == custTable.AccountNum
            &&      metCustTable.CustOperGroupId    == salesOrderGuideItem.Reference
        {
            this.processCustomer(custTable);
        }
    }

    /// <summary>
    /// Process the base record that triggered the change
    /// </summary>
    public void processSite()
    {
        CustTable       custTable;

        while select custTable
            where   custTable.InventSiteId == salesOrderGuideItem.Reference
        {
            this.processCustomer(custTable);
        }

    }

    /// <summary>
    /// Process the base record that triggered the change
    /// </summary>
    public void processState()
    {
        CustTable               custTable;
        LogisticsPostalAddress  address;
        DirPartyLocation        partyLocation;
        FieldId                 denormalizedFieldId;

        denormalizedFieldId = DirPartyLocation::denormalizedRoleFieldId(LogisticsLocationRoleType::Delivery);

        while select custTable
        
            exists join partyLocation
            where partyLocation.Party               == custTable.Party
            &&  partyLocation.IsPostalAddress       == NoYes::Yes
            &&  partyLocation.(denormalizedFieldId) == true

            exists join address
            where   address.Location    == partyLocation.Location
            &&      address.state       == salesOrderGuideItem.Reference
        {
            this.processCustomer(custTable);
        }
    }
